extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return

	var player := find_by_name(main, "Player") as CharacterBody2D
	var pressure_gate := find_by_name(main, "PressureGate") as StaticBody2D
	var plate := find_by_name(main, "PressurePlate") as Area2D

	if not check("nodes", player != null and pressure_gate != null and plate != null, "Servono i nodi Player, PressureGate e PressurePlate nella scena"):
		return

	var gate_open_init = get_prop(pressure_gate, "is_open", true)
	check("init_closed", gate_open_init == false, "PressureGate deve iniziare chiuso (is_open == false)")

	# Salita sulla piastra
	player.position = plate.global_position
	await wait_physics_frames(6)
	var plate_pressed = get_prop(plate, "is_pressed", false)
	var gate_open_pressed = get_prop(pressure_gate, "is_open", false)
	check("plate_on", plate_pressed == true, "Salendo sulla piastra is_pressed deve diventare true")
	check("gate_opened", gate_open_pressed == true, "Salendo sulla piastra PressureGate deve aprirsi tramite il segnale pressed")

	# Discesa dalla piastra
	player.position = Vector2(20, 20)
	await wait_physics_frames(6)
	var plate_released = get_prop(plate, "is_pressed", true)
	var gate_closed_released = get_prop(pressure_gate, "is_open", true)
	check("plate_off", plate_released == false, "Scendendo dalla piastra is_pressed deve tornare false")
	check("gate_closed", gate_closed_released == false, "Scendendo dalla piastra PressureGate deve richiudersi tramite il segnale released")

	# Controllo disaccoppiamento
	var gate_code := source_of("res://gate.gd")
	check("decoupled", not gate_code.contains("plate") and not gate_code.contains("PressurePlate"), "Lo script gate.gd non deve essere modificato: l'integrazione avviene tramite segnali")

